"""Read every .csv under data/, merge into all.csv with single header."""

import csv
import glob
import os

DATA_DIR = "data"
OUTPUT = "all.csv"

def main():
    csv_files = sorted(glob.glob(os.path.join(DATA_DIR, "*.csv")))
    if not csv_files:
        print("No CSV files found under data/")
        return

    with open(OUTPUT, "w", newline="") as out_f:
        writer = csv.writer(out_f)
        header_written = False
        for path in csv_files:
            with open(path, newline="") as in_f:
                reader = csv.reader(in_f)
                for row in reader:
                    if not row:
                        continue
                    if not header_written:
                        writer.writerow(row)
                        header_written = True
                    else:
                        if row == ["id", "name", "qty"]:
                            continue
                        writer.writerow(row)

    print(f"Merged {len(csv_files)} files into {OUTPUT}")

if __name__ == "__main__":
    main()

"""Read every .csv under data/, merge into all.csv with single header."""

import csv
import glob
import os

DATA_DIR = "data"
OUTPUT = "all.csv"

def main():
    csv_files = sorted(glob.glob(os.path.join(DATA_DIR, "*.csv")))
    if not csv_files:
        print("No CSV files found under data/")
        return

    with open(OUTPUT, "w", newline="") as out_f:
        writer = csv.writer(out_f)
        header_written = False
        for path in csv_files:
            with open(path, newline="") as in_f:
                reader = csv.reader(in_f)
                for row in reader:
                    if not row:
                        continue
                    if not header_written:
                        writer.writerow(row)
                        header_written = True
                    else:
                        if row == ["id", "name", "qty"]:
                            continue
                        writer.writerow(row)

    print(f"Merged {len(csv_files)} files into {OUTPUT}")

if __name__ == "__main__":
    main()

