#!/usr/bin/env python3
"""Print report file names under reports/, one per line, in report order."""

import os
import re

REPORTS_DIR = "reports"


def report_sort_key(filename: str) -> int:
    """Extract the numeric suffix from a filename like 'report-3.txt'."""
    match = re.search(r"report-(\d+)\.txt$", filename)
    if match:
        return int(match.group(1))
    return 0


def main() -> None:
    try:
        entries = os.listdir(REPORTS_DIR)
    except FileNotFoundError:
        return

    reports = [e for e in entries if re.match(r"report-\d+\.txt$", e)]
    reports.sort(key=report_sort_key)

    for r in reports:
        print(r)


if __name__ == "__main__":
    main()

