"""Rotate app.log: move entries older than 7 days before AS_OF to archive.log."""

import sys
import time
import datetime

LOG_FILE = "app.log"
ARCHIVE_FILE = "archive.log"
SEVEN_DAYS_SECS = 7 * 24 * 60 * 60


def parse_timestamp(line):
    """Parse 'YYYY-MM-DD HH:MM:SS' at the start of line, return Unix timestamp or None."""
    try:
        dt = datetime.datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
        return dt.timestamp()
    except (ValueError, IndexError):
        return None


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - SEVEN_DAYS_SECS

    # Read all entries from app.log
    try:
        with open(LOG_FILE) as f:
            lines = f.readlines()
    except FileNotFoundError:
        # No app.log — nothing to do
        return

    keep = []
    archive = []

    for line in lines:
        ts = parse_timestamp(line)
        if ts is not None and ts < cutoff:
            archive.append(line)
        else:
            keep.append(line)

    # Append archived entries to archive.log
    if archive:
        with open(ARCHIVE_FILE, "a") as f:
            f.writelines(archive)

    # Rewrite app.log with kept entries
    with open(LOG_FILE, "w") as f:
        f.writelines(keep)


if __name__ == "__main__":
    main()

