import sys
from datetime import datetime, timezone

LOG_FILE = "app.log"
ARCHIVE_FILE = "archive.log"

def parse_entry(line: str):
    """Parse a log line into (datetime, rest_of_line) or None if unparseable."""
    line = line.rstrip("\n")
    if len(line) < 19 or line[4] != "-" or line[7] != "-" or line[10] != " " or line[13] != ":" or line[16] != ":":
        return None, line
    try:
        dt = datetime.strptime(line[:19], "%Y-%m-%d %H:%M:%S")
        return dt.replace(tzinfo=timezone.utc), line
    except ValueError:
        return None, line


def main():
    if len(sys.argv) != 2:
        print("Usage: python rotate.py AS_OF", file=sys.stderr)
        sys.exit(1)

    try:
        as_of = int(sys.argv[1])
    except ValueError:
        print("AS_OF must be an integer Unix timestamp", file=sys.stderr)
        sys.exit(1)

    cutoff = as_of - 7 * 86400  # 7 days in seconds

    try:
        with open(LOG_FILE) as f:
            lines = f.readlines()
    except FileNotFoundError:
        print(f"{LOG_FILE} not found, nothing to do", file=sys.stderr)
        sys.exit(0)

    keep = []
    archive = []

    for line in lines:
        dt, raw = parse_entry(line)
        if dt is None:
            # Unparseable line — keep it in app.log by default
            keep.append(raw)
        else:
            entry_ts = dt.timestamp()
            if entry_ts < cutoff:
                archive.append(raw)
            else:
                keep.append(raw)

    # Write archive (append mode, preserve order)
    if archive:
        with open(ARCHIVE_FILE, "a") as f:
            for entry in archive:
                f.write(entry + "\n")

    # Rewrite app.log with remaining entries
    with open(LOG_FILE, "w") as f:
        for entry in keep:
            f.write(entry + "\n")


if __name__ == "__main__":
    main()
PYEOF
